// ESP32 Buzzer Melody Player with LED Visual Feedback
// Plays "Twinkle Twinkle Little Star" on a buzzer

#define BUZZER_PIN  25
#define LED1_PIN    26
#define LED2_PIN    27
#define LED3_PIN    14

// Note frequencies (Hz)
#define NOTE_C4  262
#define NOTE_D4  294
#define NOTE_E4  330
#define NOTE_F4  349
#define NOTE_G4  392
#define NOTE_A4  440
#define NOTE_B4  494
#define NOTE_C5  523
#define REST     0

// Melody: Twinkle Twinkle Little Star
const int melody[] = {
  NOTE_C4, NOTE_C4, NOTE_G4, NOTE_G4, NOTE_A4, NOTE_A4, NOTE_G4, REST,
  NOTE_F4, NOTE_F4, NOTE_E4, NOTE_E4, NOTE_D4, NOTE_D4, NOTE_C4, REST,
  NOTE_G4, NOTE_G4, NOTE_F4, NOTE_F4, NOTE_E4, NOTE_E4, NOTE_D4, REST,
  NOTE_G4, NOTE_G4, NOTE_F4, NOTE_F4, NOTE_E4, NOTE_E4, NOTE_D4, REST,
  NOTE_C4, NOTE_C4, NOTE_G4, NOTE_G4, NOTE_A4, NOTE_A4, NOTE_G4, REST,
  NOTE_F4, NOTE_F4, NOTE_E4, NOTE_E4, NOTE_D4, NOTE_D4, NOTE_C4, REST
};

// Note durations: 4 = quarter note, 8 = eighth note
const int durations[] = {
  4, 4, 4, 4, 4, 4, 2, 8,
  4, 4, 4, 4, 4, 4, 2, 8,
  4, 4, 4, 4, 4, 4, 2, 8,
  4, 4, 4, 4, 4, 4, 2, 8,
  4, 4, 4, 4, 4, 4, 2, 8,
  4, 4, 4, 4, 4, 4, 2, 8
};

const int totalNotes = sizeof(melody) / sizeof(melody[0]);

void setup() {
  Serial.begin(115200);
  Serial.println("\n=== ESP32 Buzzer Melody Player ===");
  Serial.println("Playing: Twinkle Twinkle Little Star");

  pinMode(BUZZER_PIN, OUTPUT);
  pinMode(LED1_PIN, OUTPUT);
  pinMode(LED2_PIN, OUTPUT);
  pinMode(LED3_PIN, OUTPUT);
}

void loop() {
  for (int i = 0; i < totalNotes; i++) {
    int noteDuration = 1000 / durations[i];
    int pauseBetweenNotes = noteDuration * 1.30;

    if (melody[i] != REST) {
      tone(BUZZER_PIN, melody[i], noteDuration);
      Serial.printf("Note %d: %d Hz\n", i + 1, melody[i]);
    } else {
      noTone(BUZZER_PIN);
      Serial.printf("Note %d: REST\n", i + 1);
    }

    // LED chase pattern
    digitalWrite(LED1_PIN, (i % 3 == 0) ? HIGH : LOW);
    digitalWrite(LED2_PIN, (i % 3 == 1) ? HIGH : LOW);
    digitalWrite(LED3_PIN, (i % 3 == 2) ? HIGH : LOW);

    delay(pauseBetweenNotes);

    noTone(BUZZER_PIN);
  }

  Serial.println("\nMelody complete! Restarting...\n");
  delay(1000);
}
